revoke execute on function public._demo_catalog_v3() from anon, authenticated, public;

do $do$
declare def text;
begin
  def := pg_get_functiondef('public.seed_demo_step(uuid,int)'::regprocedure);
  def := replace(def, '_demo_catalog_v2()', '_demo_catalog_v3()');
  def := replace(def, $r$case sup when 'موزع الجملة' then 3 when 'نوفا للمياه' then 2 else 1 end$r$, '1');
  if position('_demo_catalog_v3()' in def) = 0 then raise exception 'replace failed'; end if;
  execute def;
end $do$;
